PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX lei: <https://www.gleif.org/data/lei/>

SELECT ?legalName WHERE {
  lei:001GPB6A9XPE8XJICC14 gleif-L1:hasLegalName ?legalName .
}

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX jur: <https://www.gleif.org/data/jurisdiction/>

SELECT (COUNT(?e) AS ?count)
WHERE {
  ?e gleif-base:hasRegistrationStatus gleif-L1:ISSUED ;
     gleif-base:hasLegalJurisdiction jur:DE .
}

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX jur: <https://www.gleif.org/data/jurisdiction/>

SELECT ?jurisdiction (COUNT(?e) AS ?count)
WHERE {
  ?e a gleif-base:Entity ;
     gleif-base:hasLegalJurisdiction ?jurisdiction ;
     gleif-base:hasRegistrationStatus gleif-L1:ISSUED .
}
GROUP BY ?jurisdiction
ORDER BY DESC(?count)
LIMIT 5

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX gleif-re: <https://www.gleif.org/ontology/ReportingException/>
PREFIX kgx: <https://example.org/gleif-kg/ontology/>

SELECT ?parentLEI ?exceptionReason
WHERE {
  # Find the entity by legal name
  ?e a gleif-L1:RegisteredEntity ;
     gleif-L1:hasLegalName "SERRA ENERGY METALS CORP." .

  # Try to get its direct consolidation parent (if any)
  OPTIONAL {
    ?rel a gleif-base:EntityRelationship ;
         kgx:hasDirectConsolidationParent ?parent .
    ?parent gleif-L1:LEI ?parentLEI .
  }

  # If no parent, look for reporting exception
  OPTIONAL {
    ?exc a gleif-re:ReportingException ;
         gleif-re:hasReportingEntity ?e ;
         gleif-re:hasExceptionReason ?exceptionReason .
  }
}

PREFIX lei: <https://www.gleif.org/data/lei/>

SELECT ?parent
WHERE {
  lei:5493002WI30SR6SIUH74 ?p ?o .
}
LIMIT 0

PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>

